import { DOCUMENT_KINDS, expect, expectStatus, test } from "../../fixtures";

test("rejecting one document sends the whole vendor back", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
  // Arrange
  const { vendor, documents } = await factory.vendorInReview();
  const contract = await factory.extraction(documents.contract.id, "reviewer");
  expect(contract.status, "contract extraction starts pending review").toBe("pending_review");
  const reviewer = await apiAs("reviewer");

  // Act
  const decision = await reviewer.post(`/api/extractions/${contract.id}/decision`, {
    data: { decision: "reject", note: "Wrong counterparty" },
  });

  // Assert
  const decided = await expectStatus(decision, 200);
  expect(decided.status).toBe("rejected");

  // PW-12: re-read what was stored, not only the response.
  const storedExtraction = await factory.extraction(documents.contract.id, "reviewer");
  expect(storedExtraction.status).toBe("rejected");
  expect(storedExtraction.review_note).toBe("Wrong counterparty");

  const storedVendor = await expectStatus<{ status: string }>(
    await reviewer.get(`/api/vendors/${vendor.id}`),
    200,
  );
  expect(storedVendor.status).toBe("rejected");

  const trail = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  const actions = trail.items.map((e) => e.action);
  const extractionRejected = actions.indexOf("extraction.rejected");
  const vendorRejected = actions.indexOf("vendor.rejected");
  expect(extractionRejected, `audit actions: ${actions.join(", ")}`).toBeGreaterThanOrEqual(0);
  expect(vendorRejected, `audit actions: ${actions.join(", ")}`).toBeGreaterThan(extractionRejected);
});
